'use strict';
const SeenI18n=(()=>{
 const dictionary=window.SEEN_KO||{},folded=new Map(Object.entries(dictionary).map(([a,b])=>[normalize(a).toLowerCase(),b])),texts=new WeakMap(),attrs=new WeakMap(),blocks=new WeakMap(),articleBlocks=new Map();const titleSource=document.title;let observer,lang='en',busy=false;
 try{lang=localStorage.getItem('seen-language')==='ko'?'ko':'en'}catch{}
 function normalize(s){return String(s).replace(/\s+/g,' ').trim()}
 function t(value){const s=String(value??'');if(lang==='en'||!s.trim())return s;const key=normalize(s),exact=dictionary[key]||folded.get(key.toLowerCase());if(exact)return exact;
 let m;if((m=key.match(/^Question (\d+): (.+)$/)))return `문제 ${m[1]}: ${t(m[2])}`;if((m=key.match(/^Eye detail: (.+)$/)))return `눈 사진: ${t(m[1])}`;if((m=key.match(/^QUESTION (\d+) \/ (\d+)$/)))return `문제 ${m[1]} / ${m[2]}`;if((m=key.match(/^SCORE (\d+)$/)))return `점수 ${m[1]}`;if((m=key.match(/^SCREEN (\d+)(.*)$/i)))return `상영관 ${m[1]}${m[2]?' '+t(m[2].trim()):''}`;if((m=key.match(/^(?:OUTSIDE SCREEN) (\d+)$/)))return `상영관 ${m[1]} 앞`;if(key==='OUTSIDE THE GAME ROOM')return '게임방 앞';if((m=key.match(/^(\d+) LIVE · NPC HOSTS$/)))return `${m[1]}명 접속 · NPC와 함께`;
 if((m=key.match(/^Preparing the cinema · (\d+)%$/)))return `영화관 준비 중 · ${m[1]}%`;if((m=key.match(/^Would you like to play (.+)\?$/)))return `${t(m[1])} 게임을 시작할까요?`;if((m=key.match(/^This is seat ([A-E]\d+)\. Would you like to ask if you can take this seat\?$/)))return `${m[1]} 좌석입니다. 자리를 바꿔줄 수 있는지 물어볼까요?`;if((m=key.match(/^Would you let (.+) take seat ([A-E]\d+)\? If you say Yes, you’ll move to another available seat\.$/)))return `${m[1]}님에게 ${m[2]} 좌석을 양보할까요? 수락하면 다른 빈자리로 이동합니다.`;
 if((m=key.match(/^Seat ([A-E]\d+)$/)))return `좌석 ${m[1]}`;if((m=key.match(/^Seated at ([A-E]\d+)\. Enter or Stand up to explore\.$/)))return `${m[1]}에 앉았습니다. Enter 또는 일어나기로 둘러보세요.`;if((m=key.match(/^Taking seat ([A-E]\d+)…$/)))return `${m[1]}에 앉는 중…`;if((m=key.match(/^Seat ([A-E]\d+) nearby\. Enter to sit\.$/)))return `가까운 좌석 ${m[1]} · Enter로 앉기`;if((m=key.match(/^Walking over\. Tap (.+) again to talk\.$/)))return `다가가는 중입니다. ${m[1]}님을 다시 눌러 대화하세요.`;
 if((m=key.match(/^(\d+) votes? on this screen\.$/)))return `이 화면에서 ${m[1]}표를 받았어요.`;if((m=key.match(/^Leading: (.+)$/)))return `현재 1위: ${t(m[1])}`;if((m=key.match(/^(.+)’s vote (updated|counted)\. Pass the screen on\.$/)))return `${m[1]}님의 투표를 ${m[2]==='updated'?'수정':'집계'}했어요. 다음 사람에게 화면을 건네세요.`;
 if((m=key.match(/^Artwork: (.+)$/)))return `이미지 제공: ${m[1]}`;if((m=key.match(/^(\d+) November (\d{4})$/)))return `${m[2]}년 11월 ${m[1]}일`;if((m=key.match(/^(\d+) NOV$/)))return `11월 ${Number(m[1])}일`;if((m=key.match(/^ANSWER: (.+)$/)))return `정답: ${t(m[1])}`;if((m=key.match(/^View (.+), in theaters (.+)$/)))return `${t(m[1])} · ${t(m[2])} 개봉 · 영화 정보 보기`;
 for(const separator of [' — ',' · ',' / '])if(key.includes(separator))return key.split(separator).map(part=>t(part)).join(separator);
 if((m=key.match(/^(.+) · Enter to play$/)))return `${t(m[1])} · Enter로 시작`;
 return s;
 }
 function ignored(e){return !e||e.closest('script,style,textarea,[data-no-translate],.reader-comment,[contenteditable="true"]')}
 function translateText(node){if(ignored(node.parentElement)||node.parentElement.closest('[data-i18n-article-block]'))return;const current=node.nodeValue;let state=texts.get(node);if(!state||current!==state.output)state={source:current,output:current};const translated=t(state.source);if(current!==translated)node.nodeValue=translated;state.output=translated;texts.set(node,state)}
 function ensureButtons(){for(const host of document.querySelectorAll('.site-header,.welcome-top,.game-toolbar,.screen-article-toolbar,.film-detail-top,.upcoming-toolbar,.article-toolbar,.dialog-toolbar,#npc-dialog,#game-confirm')){if(host.querySelector('[data-language-toggle]'))continue;const b=document.createElement('button');b.type='button';b.className='language-toggle';b.dataset.languageToggle='';b.dataset.noTranslate='';b.onclick=()=>setLanguage(lang==='en'?'ko':'en');const close=host.querySelector('.icon-close,.board-close');if(close)host.insertBefore(b,close);else if(host.classList.contains('site-header'))host.insertBefore(b,host.querySelector('button'));else host.append(b)}for(const b of document.querySelectorAll('[data-language-toggle]')){b.textContent=lang==='en'?'한국어':'EN';b.setAttribute('aria-label',lang==='en'?'한국어로 보기':'View in English');b.setAttribute('lang',lang==='en'?'ko':'en')}}
 function buildArticleBlocks(){const sources=typeof screeningArticles!=='undefined'?screeningArticles:typeof articles!=='undefined'?articles:{};if(sources.credits){const root=document.createElement('div');root.innerHTML=sources.credits.body;for(const [index,items]of Object.entries(window.SEEN_KO_CREDIT_LISTS||{})){const ul=root.children[+index],clone=ul.cloneNode(true);[...clone.children].forEach((li,i)=>{const a=li.querySelector('a');a.textContent=items[i][0];const extra=li.querySelectorAll('a')[1];li.replaceChildren(a,document.createTextNode('. '+items[i][1]));if(extra){extra.textContent='공식 줄거리 발표';li.append(' ',extra)}});articleBlocks.set(ul.outerHTML,clone.innerHTML)}}for(const [id,entries]of Object.entries(window.SEEN_KO_ARTICLES||{})){if(!sources[id])continue;const root=document.createElement('div');root.innerHTML=sources[id].body;[...root.children].forEach((e,i)=>{let ko=entries[i];if(!ko)return;if(ko==='@CREDIT'){const a=e.querySelector('a');ko='영화 정보·이미지: '+(a?a.outerHTML:'A24')+'. SEEN을 위해 작성한 해석 기사입니다.'}articleBlocks.set(e.outerHTML,ko)})}}
 function localizeArticles(){for(const root of document.querySelectorAll('.screen-article-body,.article-body'))for(const e of root.children){if(e.tagName==='BUTTON')continue;let state=blocks.get(e);if(!state){const ko=articleBlocks.get(e.outerHTML);if(!ko)continue;state={source:e.innerHTML,ko};blocks.set(e,state);e.dataset.i18nArticleBlock=''}const html=lang==='ko'?state.ko:state.source;if(e.innerHTML!==html)e.innerHTML=html}}
 function sweep(){if(busy)return;busy=true;observer?.disconnect();ensureButtons();localizeArticles();const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(walker.nextNode())translateText(walker.currentNode);for(const e of document.querySelectorAll('[aria-label],[placeholder],[title],[alt]')){if(ignored(e)||e.hasAttribute('data-language-toggle'))continue;let state=attrs.get(e)||{};for(const attr of ['aria-label','placeholder','title','alt']){if(!e.hasAttribute(attr))continue;const value=e.getAttribute(attr),old=state[attr];const source=old&&value===old.output?old.source:value,output=t(source);if(output!==value)e.setAttribute(attr,output);state[attr]={source,output}}attrs.set(e,state)}document.documentElement.lang=lang;document.title=t(titleSource);busy=false;observer?.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','placeholder','title','alt']})}
 function setText(node,value){const source=String(value),output=t(source);if(node.textContent!==output)node.textContent=output;if(node.firstChild?.nodeType===Node.TEXT_NODE)texts.set(node.firstChild,{source,output})}
 function setLanguage(next){if(next!=='en'&&next!=='ko')return;lang=next;try{localStorage.setItem('seen-language',lang)}catch{}sweep();dispatchEvent(new Event('resize'));document.dispatchEvent(new CustomEvent('seen-language-change',{detail:{language:lang}}))}
 document.addEventListener('DOMContentLoaded',()=>{buildArticleBlocks();observer=new MutationObserver(()=>sweep());sweep()},{once:true});
 return{t,text:setText,setLanguage,get language(){return lang},refresh:sweep};
})();
